{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-hfqsmN/src/policies.js","content":"/**
 * Per-key state machines for the two policy kinds. Each policy owns one
 * independent state per key, created lazily the first time that key reaches
 * it. All arithmetic uses BigInt so that fractional token accumulation and
 * arbitrarily large ticks/counts never lose precision to floating point.
 */

export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  advance(key, tick) {
    const existing = this.states.get(key)
    if (!existing) {
      this.states.set(key, { numerator: this.capacity * this.per, lastTick: tick })
      return
    }
    const dt = tick - existing.lastTick
    if (dt > 0n) {
      const max = this.capacity * this.per
      let numerator = existing.numerator + this.refill * dt
      if (numerator > max) numerator = max
      existing.numerator = numerator
      existing.lastTick = tick
    }
  }

  allows(key) {
    return this.states.get(key).numerator >= this.per
  }

  record(key) {
    this.states.get(key).numerator -= this.per
  }
}

export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let ticks = this.states.get(key)
    if (!ticks) {
      ticks = []
      this.states.set(key, ticks)
    }
    const threshold = tick - this.span
    let cut = 0
    while (cut < ticks.length && ticks[cut] <= threshold) cut++
    if (cut > 0) ticks.splice(0, cut)
  }

  allows(key) {
    return BigInt(this.states.get(key).length) < this.limit
  }

  record(key, tick) {
    this.states.get(key).push(tick)
  }
}
"}

