{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-hfqsmN/src/limiter.js","content":"/**
 * Parses a limiter file and replays its events in one pass, since a parse
 * failure must leave standard output untouched: nothing is printed until the
 * whole file has been walked without error.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

const TOKEN_RE = /^[A-Za-z0-9_./:-]+$/
const COUNT_RE = /^(0|[1-9][0-9]*)$/

class LineError extends Error {}

function parseCount(str, field, least) {
  if (!COUNT_RE.test(str)) throw new LineError(`${field} must be an integer of at least ${least}`)
  const value = BigInt(str)
  if (value < BigInt(least)) throw new LineError(`${field} must be an integer of at least ${least}`)
  return value
}

function parseName(str, kind) {
  if (!TOKEN_RE.test(str)) throw new LineError(`${kind} ${str}`)
  return str
}

/**
 * Runs a limiter file through the simulator.
 * @param {string} input the raw file contents read from standard input
 * @param {'replay'|'summary'} mode which report to produce
 * @returns {{ok: true, output: string} | {ok: false, message: string}}
 */
export function run(input, mode) {
  const lines = input.split('\n')
  if (input.endsWith('\n')) lines.pop()

  const policies = new Map()
  const routes = []
  const routesByPrefix = new Map()
  let eventsSeen = false
  let lastTick = null

  const verdicts = []
  const summaryMap = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    try {
      switch (directive) {
        case 'bucket': {
          if (tokens.length !== 5) throw new LineError('expected bucket <name> <capacity> <refill> <per>')
          const name = parseName(tokens[1], 'invalid policy name')
          const capacity = parseCount(tokens[2], 'capacity', 1)
          const refill = parseCount(tokens[3], 'refill', 0)
          const per = parseCount(tokens[4], 'per', 1)
          if (eventsSeen) throw new LineError('declarations must come before the first event')
          if (policies.has(name)) throw new LineError(`policy ${name} is declared twice`)
          policies.set(name, new TokenBucket(capacity, refill, per))
          break
        }
        case 'window': {
          if (tokens.length !== 4) throw new LineError('expected window <name> <limit> <span>')
          const name = parseName(tokens[1], 'invalid policy name')
          const limit = parseCount(tokens[2], 'limit', 0)
          const span = parseCount(tokens[3], 'span', 1)
          if (eventsSeen) throw new LineError('declarations must come before the first event')
          if (policies.has(name)) throw new LineError(`policy ${name} is declared twice`)
          policies.set(name, new SlidingWindow(limit, span))
          break
        }
        case 'route': {
          if (tokens.length < 3) throw new LineError('expected route <prefix> <policy>...')
          const prefix = parseName(tokens[1], 'invalid route prefix')
          const policyNames = tokens.slice(2)
          if (eventsSeen) throw new LineError('declarations must come before the first event')
          for (const name of policyNames) {
            if (!policies.has(name)) throw new LineError(`unknown policy ${name}`)
          }
          if (routesByPrefix.has(prefix)) throw new LineError(`prefix ${prefix} is routed twice`)
          const route = { prefix, policyNames }
          routesByPrefix.set(prefix, route)
          routes.push(route)
          break
        }
        case 'event': {
          if (tokens.length !== 3) throw new LineError('expected event <tick> <key>')
          const tick = parseCount(tokens[1], 'tick', 0)
          const key = parseName(tokens[2], 'invalid key')
          if (lastTick !== null && tick < lastTick) throw new LineError(`tick ${tick} is before tick ${lastTick}`)
          eventsSeen = true
          lastTick = tick

          let best = null
          for (const route of routes) {
            if (key.startsWith(route.prefix)) {
              if (!best || route.prefix.length > best.prefix.length) best = route
            }
          }

          let allow = true
          let denyPolicy = null
          if (best) {
            const policyObjs = best.policyNames.map((name) => policies.get(name))
            for (const policy of policyObjs) policy.advance(key, tick)
            for (let p = 0; p < policyObjs.length; p++) {
              if (!policyObjs[p].allows(key)) {
                allow = false
                denyPolicy = best.policyNames[p]
                break
              }
            }
            if (allow) {
              for (const policy of policyObjs) policy.record(key, tick)
            }
          }

          verdicts.push({ tick, key, allow, denyPolicy })
          let stats = summaryMap.get(key)
          if (!stats) {
            stats = { allowed: 0, denied: 0 }
            summaryMap.set(key, stats)
          }
          if (allow) stats.allowed++
          else stats.denied++
          break
        }
        default:
          throw new LineError(`unknown directive ${directive}`)
      }
    } catch (err) {
      if (err instanceof LineError) return { ok: false, message: `line ${lineNo}: ${err.message}` }
      throw err
    }
  }

  let output = ''
  if (mode === 'replay') {
    for (const v of verdicts) {
      output += v.allow ? `${v.tick} ${v.key} allow\n` : `${v.tick} ${v.key} deny ${v.denyPolicy}\n`
    }
  } else {
    const keys = [...summaryMap.keys()].sort()
    let totalAllowed = 0
    let totalDenied = 0
    for (const key of keys) {
      const stats = summaryMap.get(key)
      output += `${key} allowed=${stats.allowed} denied=${stats.denied}\n`
      totalAllowed += stats.allowed
      totalDenied += stats.denied
    }
    output += `total allowed=${totalAllowed} denied=${totalDenied}\n`
  }

  return { ok: true, output }
}
"}

