          const capacity = parseCount(tokens[2], 'capacity', 1)
          const refill = parseCount(tokens[3], 'refill', 0)
          const per = parseCount(tokens[4], 'per', 1)
          if (eventsSeen) throw new LineError('declarations must come before the first event')
          if (policies.has(name)) throw new LineError(`policy ${name} is declared twice`)
