    let totalAllowed = 0
    let totalDenied = 0
    for (const key of keys) {
      const stats = summaryMap.get(key)
      output += `${key} allowed=${stats.allowed} denied=${stats.denied}\n`
      totalAllowed += stats.allowed
      totalDenied += stats.denied
    }
    output += `total allowed=${totalAllowed} denied=${totalDenied}\n`
  }

  return { ok: true, output }
}
